# Script that runs a number of simulations in which stimulus is given to A with different feedback selectivity and G values
# The selectivity-G values are taken based on the csv generated by the phase_diagram_selectivity_G_and_save_pairs_for_decoding.ipynb file
# The output is used for decoding the stimulus from early visual cortex area
import os
import sys
import math
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import random

# Add the project root to the PYTHONPATH
script_dir = os.path.dirname(os.path.abspath(__file__))
project_root = os.path.abspath(os.path.join(script_dir, '..'))
sys.path.append(project_root)

from src.data import load_and_preprocess_data as get_data
from src.models import WorkingMemoryNetwork, balloon_windkessel_A, balloon_windkessel_B
from config.WM_params import WorkingMemoryParameters
import time

mixed_selectivity_vals = [1, 0.95, 0.9, 0.85, 0.8, 0.75, 0.7, 0.65, 0.6, 0.55, 0.5]
G_vals = [0.83, 0.91, 1.03, 1.19, 1.34, 1.45, 1.55, 1.71, 1.91, 1.25, 1.02] # initially for 0.7 it was 1.58, but sometimes there are spont switches, so 1.55 works better
# also very rarely 1.93 for 0.6 resulted in area 90 spontaneously switching, so use 1.91 instead
# need to save all traces for the whole brain
for G, selectivity in zip(G_vals, mixed_selectivity_vals):
    population_to_stimulate = 0
    avg_firing_rate_pop = []
    firing_rate_pop = []
    bold_signal = []
    n_trials = 10
    for trial in range(n_trials):
        print(f'G: {G}, selectivity: {selectivity}')

        random_seed = random.randint(0, 10000)
        outside_rng = np.random.default_rng(random_seed)

        data_activation_maps = False # Turn True if we need data to plot cue and delay activation maps
        target_names = ['Vis_5', 'Vis_7', 'Vis_9'] # Areas which receive input stimulation
        ALPHA = 1.34
        J_MAX = 0.3

        data = get_data(data_folder_path='../../../data/processed')
        area_names = data['area_names']
        SLN = data['SLN']
        W = data['W']
        h = data['hier_vals']
        normalized_nmda_rd = data['nmda_rd']

        # Initial condition and parameters
        N = len(area_names)
        Y0 = np.zeros((N, 8))
        Y0[:, 0:3] = 5 * (1 + np.tanh(outside_rng.normal(0, 2, (N, 3)))) # r values are initialized randomly between 0 and 10
        WM_params = WorkingMemoryParameters()
        WM_params.update(G=G, ALPHA=ALPHA, J_MAX=J_MAX, TAU_NOISE=2e-3) # Update G and alpha to optimal settings
        # Generate the network
        WM_network = WorkingMemoryNetwork(area_names=area_names, Y0=Y0, W=W,
                                        F=SLN, h=h,
                                        normalized_nmda_rd=normalized_nmda_rd,
                                        params=WM_params, gradient='NMDA',
                                        selectivity=selectivity)
        # Run the simulation
        t_end = 50
        dt = 0.5e-3
        stim_start_time = 20
        stim_duration = 0.5
        t_eval = np.arange(0, t_end+dt, dt) # Time points of the simulation
        I_ext_strength = np.zeros((N, 3))

        # Find indexes of the target names in the list
        rows = np.where(np.isin(area_names, target_names))[0]
        I_ext_strength[rows, population_to_stimulate] = 0.3

        start = time.perf_counter()
        state_history, input_history = WM_network.run(t_end=t_end, dt=dt, I_ext_strengths=np.stack([I_ext_strength]),
                                                    ts_ext_start=np.array([stim_start_time]),
                                                    ts_ext_end=np.array([stim_start_time + stim_duration]))
        end = time.perf_counter()
        print("Elapsed (after compilation) = {}s".format((end - start)))
        firing_rate_pop.append((np.array(state_history[:, :, 0]), np.array(state_history[:, :, 1]), selectivity)) # Save firing rate traces for both populations
        avg_firing_rates_A, avg_firing_rates_B = WM_network.save_avg_firing_rates_last_two_seconds(variables=['r_A', 'r_B'])
        avg_firing_rate_pop.append((avg_firing_rates_A[:], avg_firing_rates_B[:], selectivity))
        spont_switch, pop_switch = WM_network.check_spontaneous_switch_to_high_state(stim_start_time)
        print(f'There is spontaneous switch to higher state: {spont_switch}, in populations {pop_switch}')
        bold_A = np.array(balloon_windkessel_A(state_history, dt))
        bold_B = np.array(balloon_windkessel_B(state_history, dt))

        bold_signal.append((np.array(bold_A[:, :]), np.array(bold_B[:, :]), selectivity))
    avg_firing_rate_arr = np.array(avg_firing_rate_pop, dtype=object)
    bold_signal_arr = np.array(bold_signal, dtype=object)
    firing_rate_arr = np.array(firing_rate_pop, dtype=object)
    np.save(f'../results/decoding/firing_rate_{selectivity}.npy', avg_firing_rate_arr)
    np.save(f'../results/decoding/bold_signal_{selectivity}.npy', bold_signal_arr)
    np.save(f'../results/decoding/activity_trace_fr_{selectivity}.npy', firing_rate_arr)